using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
using SimplePZMapmaker.Web.Services;
using System.IO.Compression;
using System.Text.Json;
public static class GameplayAuthoringTests
{
 public static IEnumerable<(string,Action)> Cases()
 {
  yield return("model footprint requires connected anchored cells and checks full bounds",()=>{var m=Model();m.Footprint=[new(0,0),new(1,0),new(1,1)];StaticModelPlacement.Validate(m,8,8);m.X=7;Reject(()=>StaticModelPlacement.Validate(m,8,8));m.X=0;m.Footprint=[new(0,0),new(2,0)];Reject(()=>StaticModelPlacement.Validate(m,8,8));m.Footprint=[new(1,0)];Reject(()=>StaticModelPlacement.Validate(m,8,8));m.Footprint=[new(0,0),new(0,0)];Reject(()=>StaticModelPlacement.Validate(m,8,8));});
  yield return("door native edges keys lights and loot profile constraints validate",()=>{var m=Model();m.Profile="door";m.Door=new(){Direction="w",KeyId=42,Locked=true};StaticModelPlacement.Validate(m,8,8);m.Door.Direction="e";Reject(()=>StaticModelPlacement.Validate(m,8,8));m.Door.Direction="w";m.Footprint=[new(0,0),new(1,0)];Reject(()=>StaticModelPlacement.Validate(m,8,8));m.Footprint=[];m.Profile="light";m.Door=null;m.Light=new(){Rgb=[.1,.5,1],Radius=20};StaticModelPlacement.Validate(m,8,8);m.Light.Rgb=[double.NaN,0,0];Reject(()=>StaticModelPlacement.Validate(m,8,8));m.Light=null;m.Profile="scenery";m.LootDistribution="StoreShelf";Reject(()=>StaticModelPlacement.Validate(m,8,8));m.Profile="container";StaticModelPlacement.Validate(m,8,8);});
  yield return("malformed footprint auto version promotion stays null safe",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var m=Model();m.Footprint=null!;p.StaticModels.Add(m);_ =p.Version;Reject(()=>ProjectValidator.Validate(p));});
  yield return("building footprint catches hole secondary furniture and wall crossings",()=>{var b=new Building{Width=8,Height=8};BuildingDesigner.Generate(b,1,42);var f=b.Design!.Floors[0];f.Cells=new string('0',64);f.Rooms=new(){["0"]="hall"};f.Objects.Clear();f.Edges=BuildingDesigner.AutoEdges(b,f,0);var m=Model();m.X=2;m.Y=2;m.Footprint=[new(0,0),new(1,0)];f.StaticModels.Add(m);BuildingDesigner.Validate(b,false);var cells=f.Cells.ToCharArray();cells[2*8+3]='.';f.Cells=new(cells);Reject(()=>BuildingDesigner.Validate(b,false));f.Cells=new string('0',64);f.Edges.Add(new(){X=3,Y=2,Edge="w",Kind="wall"});Reject(()=>BuildingDesigner.Validate(b,false));f.Edges.RemoveAt(f.Edges.Count-1);f.Objects.Add(new(){X=3,Y=2,Kind="seat"});Reject(()=>BuildingDesigner.Validate(b,false));});
  yield return("game zone layers overlap rules vehicle water and building rejection",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.GameZones.Add(new(){Name="Forest",Type="Forest",X=20,Y=20,Width=16,Height=16});p.GameZones.Add(new(){Name="Cars",Type="Vehicle",X=20,Y=20,Width=3,Height=5,VehicleDistribution="parkingstall"});GameZones.ValidateProject(p);p.Terrain[20*p.Width+20]=Terrain.Water;Reject(()=>GameZones.ValidateProject(p));p.Terrain[20*p.Width+20]=Terrain.Grass;p.Buildings.Add(new(){X=20,Y=20,Width=12,Height=10});Reject(()=>GameZones.ValidateProject(p));p.Buildings.Clear();p.GameZones.Add(new(){Name="Overlap",Type="Farm",X=25,Y=25});Reject(()=>GameZones.ValidateProject(p));});
  yield return("authored native zone export removes intersecting automatic rectangles",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.GameZones.Add(new(){Name="custom\"forest",Type="DeepForest",X=1,Y=1,Width=3,Height=3});p.GameZones.Add(new(){Name="Editor label",Type="ParkingStall",X=10,Y=10,Width=3,Height=5,VehicleDistribution="parkingstall",Direction="E",FaceDirection=false});var lua=GameZonesExporter.ObjectsLua(p);if(!lua.Contains("custom\\\"forest")||!lua.Contains("Direction=\"E\", FaceDirection=false")||!lua.Contains("name=\"parkingstall\", type=\"ParkingStall\"")||lua.Contains($"x={p.WorldX*256}, y={p.WorldY*256}, z=0, width=8, height=8"))throw new Exception("Custom zones or automatic zone subtraction lost.");});
  yield return("actual map and stitched world archives carry authored native vehicle zones",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.GameZones.Add(new(){Name="Car park",Type="ParkingStall",X=75,Y=75,Width=3,Height=5,VehicleDistribution="parkingstall",Direction="E"});string Objects(byte[] bytes){using var z=new ZipArchive(new MemoryStream(bytes));using var r=new StreamReader(z.Entries.Single(e=>e.FullName.EndsWith("/objects.lua")).Open());return r.ReadToEnd();}var expected=$"x={p.WorldX*256+75}, y={p.WorldY*256+75}, z=0, width=3, height=5";var map=Objects(NativeMapExporter.Export(p));var world=new WorldProject{Maps=[new(){Project=p}],Buildings=[new(){X=p.WorldX*256+20,Y=p.WorldY*256+20,Width=8,Height=8}]};var projected=WorldAssembler.ProjectSection(world,world.Maps[0]);if(!ReferenceEquals(projected.GameZones,p.GameZones)||!ReferenceEquals(projected.LinearFeatures,p.LinearFeatures))throw new Exception("Shared building projection lost authoring layers.");var stitched=Objects(NativeWorldExporter.Export(world));foreach(var lua in new[]{map,stitched})if(!lua.Contains("type=\"ParkingStall\"")||!lua.Contains("Direction=\"E\"")||!lua.Contains(expected))throw new Exception("Authored vehicle zone disappeared from the real exported archive.");});
  yield return("shared native containers retain registered loot provider dependency in world mod",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var b=new Building{X=p.WorldX*256+20,Y=p.WorldY*256+20,Width=8,Height=8};BuildingDesigner.Generate(b,1,42);var f=b.Design!.Floors[0];f.Cells=new string('0',64);f.Rooms=new(){["0"]="hall"};f.Objects.Clear();f.Edges=BuildingDesigner.AutoEdges(b,f,0);var model=Model();model.Profile="container";model.X=2;model.Y=2;model.LootDistribution="StoreShelf";model.LootRequiredMods=["SharedLootProvider"];f.StaticModels.Add(model);var world=new WorldProject{Maps=[new(){Project=p}],Buildings=[b]};using var z=new ZipArchive(new MemoryStream(NativeWorldExporter.Export(world)));using var r=new StreamReader(z.Entries.Single(e=>e.FullName.EndsWith("/mod.info")).Open());if(!r.ReadToEnd().Contains("require=SharedLootProvider"))throw new Exception("The world omitted its shared container's registered loot provider.");});
  yield return("literal Lua registrations ignore comments strings nested metadata and computed code",()=>{var lua="-- ProceduralDistributions.list = { Evil={} }\nlocal str=[[VehicleZoneDistribution.fake = {}]]; ProceduralDistributions.list={ Valid={rolls=3,junk={items={}}}, Other={} }; VehicleZoneDistribution.parkingstall={}; VehicleZoneDistribution.parkingstall.vehicles={}; VehicleZoneDistribution[key]={}; --[=[VehicleZoneDistribution.nope={}]=]";if(!LiteralDistributionNames.Read(lua,"ProceduralDistributions.list",true).SequenceEqual(new[]{"Other","Valid"})||!LiteralDistributionNames.Read(lua,"VehicleZoneDistribution",false).SequenceEqual(new[]{"parkingstall"}))throw new Exception("Unsafe or nested Lua declaration accepted.");});
  yield return("interactive native export preserves masks doors actual light and declarative loot",()=>{var a=Model();a.Profile="container";a.Footprint=[new(0,0),new(1,0)];a.LootDistribution="StoreShelf";a.Light=new(){Rgb=[1,.2,.1],Radius=9};var b=Model();b.Profile="door";b.Door=new(){Direction="w",Locked=true,KeyId=55};using var ms=new MemoryStream();using(var z=new ZipArchive(ms,ZipArchiveMode.Create,true))StaticModelExporter.Write(z,"GameplayFixture",[new(a,100,100,-1),new(b,110,110,0)]);using var zip=new ZipArchive(new MemoryStream(ms.ToArray()));string Read(string suffix){using var r=new StreamReader(zip.Entries.Single(e=>e.FullName.EndsWith(suffix)).Open());return r.ReadToEnd();}string lua=Read("Gameplay.lua"),binding=Read("Loot.lua");if(!lua.Contains("x=101,y=100,z=-1,anchor=false")||!lua.Contains("IsoLightSource.new")||!lua.Contains("getCell():addLamppost")||!lua.Contains("setLockedByKey")||!lua.Contains("doRollItem(distribution,container,0,nil,true,nil)")||!lua.Contains("ModData.getOrCreate")||!binding.Contains("name=\"StoreShelf\""))throw new Exception("Interactive export lost actual game semantics.");var root=Environment.GetEnvironmentVariable("PZMAP_WORKSPACE");if(root is not null){var dir=Path.Combine(root,"work","gameplay-inspect");Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"interactive-fixture.zip"),ms.ToArray());foreach(var e in zip.Entries.Where(e=>e.FullName.EndsWith(".lua")||e.FullName.EndsWith(".txt"))){using var r=new StreamReader(e.Open());File.WriteAllText(Path.Combine(dir,Path.GetFileName(e.FullName)),r.ReadToEnd());}}});
  yield return("installed gameplay declarations expose canonical owners without executing Lua",()=>{var game=Environment.GetEnvironmentVariable("PZMAP_GAME_PATH")??"";if(!Directory.Exists(game))return;var catalog=new GameplayCatalog(new GameAssetCatalog(Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")!,game));var json=JsonSerializer.Serialize(catalog.Snapshot(),NativeMapExporter.JsonOptions);using var data=JsonDocument.Parse(json);if(data.RootElement.GetProperty("loot").GetArrayLength()<1000||!data.RootElement.GetProperty("vehicles").EnumerateArray().Any(e=>e.GetProperty("id").GetString()=="parkingstall")||json.Contains(game))throw new Exception("Installed literal registrations missing or private paths exposed.");var m=Model();m.Profile="container";m.LootDistribution="AmbulanceDriverOutfit";catalog.Validate(m);m.LootSourceId="wrong";Reject(()=>catalog.Validate(m));});
 }
 private static StaticModelPlacement Model()=>new(){ModelId="Base.BeerBottle",Profile="obstacle"};private static void Reject(Action a){try{a();}catch(ArgumentException){return;}throw new Exception("Invalid gameplay authoring accepted.");}
}
